        sc_format_apdu(card, &apdu, SC_APDU_CASE_3_SHORT, 0x46,  0x00,
                        data->key_id);
        apdu.le      = 0;
        sbuf[0] = (u8)(data->key_length >> 8);
        sbuf[1] = (u8)(data->key_length);
        apdu.data    = sbuf;
        apdu.lc      = 2;
        apdu.datalen = 2;
        r = sc_transmit_apdu(card, &apdu);
