    if (chunk_size > SC_MAX_ATR_SIZE)
        chunk_size = SC_MAX_ATR_SIZE;
    else
        reader->atr.len = chunk_size;

    if (chunk_size > 0)
        memcpy(reader->atr.value, chunk, chunk_size);

    return SC_SUCCESS;
}

